WITH row AS (UPDATE zc_private.discord_watch SET paused=$2,last_error=$3,last_delivery_key=$4, date_updated=clock_timestamp() WHERE id=$1 RETURNING *) SELECT jsonb_build_object('id',id::text, 'discordId',discord_id::text,'kind',kind,'targetId',target_id,'paused',paused,'lastError',last_error, 'lastDeliveryKey',last_delivery_key,'dateCreated',to_char(date_created AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM row
